from datetime import date, datetime
from decimal import Decimal, InvalidOperation

_BUCKET_KEYS = ("current", "1-30", "31-60", "61-90", "90+")
_TWO_PLACES = Decimal("0.00")

def _parse_date_value(value):
    # Accept datetime by converting to date, date as-is, strict YYYY-MM-DD string.
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if isinstance(value, str):
        # Enforce strict YYYY-MM-DD shape: 10 chars with dashes.
        if len(value) != 10 or value[4] != "-" or value[7] != "-":
            raise ValueError(f"unparseable date string: {value!r}")
        try:
            return date.fromisoformat(value)
        except ValueError:
            raise ValueError(f"unparseable date string: {value!r}")
    raise ValueError(f"invalid date value: {value!r}")

def _parse_amount(value):
    # bool is subclass of int but is not a valid amount.
    if isinstance(value, bool):
        raise ValueError(f"invalid amount: {value!r}")
    if isinstance(value, float):
        raise ValueError(f"float amount not allowed: {value!r}")
    if isinstance(value, int):
        return Decimal(value)
    if isinstance(value, Decimal):
        if not value.is_finite():
            raise ValueError(f"non-finite amount: {value!r}")
        return value
    if isinstance(value, str):
        try:
            d = Decimal(value)
        except (InvalidOperation, ValueError, AttributeError):
            raise ValueError(f"unparseable amount: {value!r}")
        if not d.is_finite():
            raise ValueError(f"non-finite amount: {value!r}")
        return d
    raise ValueError(f"invalid amount: {value!r}")

def aging_buckets(invoices: list[dict], as_of: date) -> dict[str, Decimal]:
    as_of_date = _parse_date_value(as_of)
    totals = {
        "current": Decimal(0),
        "1-30": Decimal(0),
        "31-60": Decimal(0),
        "61-90": Decimal(0),
        "90+": Decimal(0),
    }
    for inv in invoices:
        if not isinstance(inv, dict):
            raise ValueError(f"invalid invoice: {inv!r}")
        if "due_date" not in inv or "amount" not in inv:
            raise ValueError("missing due_date or amount")
        due_date = _parse_date_value(inv["due_date"])
        amount = _parse_amount(inv["amount"])
        days_overdue = (as_of_date - due_date).days
        if days_overdue <= 0:
            bucket = "current"
        elif 1 <= days_overdue <= 30:
            bucket = "1-30"
        elif 31 <= days_overdue <= 60:
            bucket = "31-60"
        elif 61 <= days_overdue <= 90:
            bucket = "61-90"
        else:
            bucket = "90+"
        totals[bucket] += amount
    result: dict[str, Decimal] = {}
    for key in _BUCKET_KEYS:
        result[key] = totals[key].quantize(_TWO_PLACES)
    return result
